-- Widgets
------------------------------------------------------------
local function makeButton(parent, text, order, color)
	local b = new("TextButton", {
		LayoutOrder = order,
		Size = UDim2.new(1, -4, 0, 32),
		BackgroundColor3 = color,
		BackgroundTransparency = 0.1,
		Text = text,
		Font = Enum.Font.GothamBold,
		TextSize = 13,
		TextColor3 = C.text,
	}, parent)
	corner(b, 8)
	return b
end

local function makeToggle(parent, text, order, initial, callback)
	local btn = new("TextButton", {
		LayoutOrder = order,
		Size = UDim2.new(1, -4, 0, 32),
		BackgroundColor3 = C.dark,
		BackgroundTransparency = 0.3,
		Text = "",
	}, parent)
	corner(btn, 8)
	new("TextLabel", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -64, 1, 0),
		Position = UDim2.fromOffset(10, 0),
		Font = Enum.Font.GothamMedium,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		TextColor3 = C.text,
		Text = text,
	}, btn)
	local pill = new("Frame", {
		Size = UDim2.fromOffset(38, 20),
		Position = UDim2.new(1, -48, 0.5, -10),
		BorderSizePixel = 0,
	}, btn)
	corner(pill, 10)
	local knob = new("Frame", {
		Size = UDim2.fromOffset(16, 16),
		BackgroundColor3 = C.text,
		BorderSizePixel = 0,
	}, pill)
	corner(knob, 8)

	local state = initial and true or false
	local function paint(animate)
		local pc = state and C.green or C.gray
		local kp = state and UDim2.fromOffset(20, 2) or UDim2.fromOffset(2, 2)
		if animate then
			local ti = TweenInfo.new(0.12)
			TweenService:Create(pill, ti, { BackgroundColor3 = pc }):Play()
			TweenService:Create(knob, ti, { Position = kp }):Play()
		else
			pill.BackgroundColor3 = pc
			knob.Position = kp
		end
	end
	paint(false)

	btn.MouseButton1Click:Connect(function()
		state = not state
		paint(true)
		local ok, err = pcall(callback, state)
		if not ok then warn("[FrostBoost] " .. text .. ": " .. tostring(err)) end
	end)

	return {
		set = function(on)
			on = on and true or false
			if on == state then return end
			state = on
			paint(true)
		end,
		destroy = function() btn:Destroy() end,
	}
end

local function makeBox(parent, order, placeholder, text, height, multi)
	local box = new("TextBox", {
		LayoutOrder = order,
		Size = UDim2.new(1, -4, 0, height or 30),
		BackgroundColor3 = C.dark,
		BackgroundTransparency = 0.25,
		BorderSizePixel = 0,
		Font = Enum.Font.Gotham,
		TextSize = 13,
		TextColor3 = C.text,
		PlaceholderText = placeholder,
		PlaceholderColor3 = Color3.fromRGB(140, 150, 170),
		Text = text or "",
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = multi and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
		MultiLine = multi and true or false,
		TextWrapped = multi and true or false,
	}, parent)
	corner(box, 8)
	new("UIPadding", {
		PaddingLeft = UDim.new(0, 8),
		PaddingRight = UDim.new(0, 8),
		PaddingTop = UDim.new(0, multi and 6 or 0),
	}, box)
	return box
end

------------------------------------------------------------
-- Dragging (mouse + touch)
------------------------------------------------------------
local dragging, dragStart, startPos = false, nil, nil
header.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1
		or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		startPos = main.Position
		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then dragging = false end
		end)
	end
end)
track(UserInputService.InputChanged:Connect(function(input)
	if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
		or input.UserInputType == Enum.UserInputType.Touch) then
		local d = input.Position - dragStart
		main.Position = UDim2.new(
			startPos.X.Scale, startPos.X.Offset + d.X,
			startPos.Y.Scale, startPos.Y.Offset + d.Y
		)
	end
end))

------------------------------------------------------------
-- Shadows
------------------------------------------------------------
local shadowsOn = Lighting.GlobalShadows
local shadowGen = 0
local shadowConn = nil

local function setShadows(on)
	shadowsOn = on
	shadowGen += 1
	local gen = shadowGen
	Lighting.GlobalShadows = on
	if shadowConn then
		shadowConn:Disconnect()
		shadowConn = nil
	end
	if not on then
		shadowConn = workspace.DescendantAdded:Connect(function(d)
			if d:IsA("BasePart") then pcall(function() d.CastShadow = false end) end
		end)
	end
	task.spawn(function()
		local n = 0
		for _, d in ipairs(workspace:GetDescendants()) do
			if shadowGen ~= gen then return end
			if d:IsA("BasePart") and not d:IsA("Terrain") then
				pcall(function() d.CastShadow = on end)
			end
			n += 1
			if n % 500 == 0 then task.wait() end
		end
	end)
end

------------------------------------------------------------
-- FPS boost
------------------------------------------------------------
local boost = { on = false, saved = {}, conn = nil, gen = 0, prevShadows = true }
local shadowToggle = nil

local function remember(inst, prop)
	local s = boost.saved
	s[#s + 1] = { inst, prop, inst[prop] }
end

local function optimize(inst)
	if inst:IsA("Terrain") then return end
	if inst:IsA("BasePart") then
		remember(inst, "Material")
		remember(inst, "Reflectance")
		inst.Material = Enum.Material.SmoothPlastic
		inst.Reflectance = 0
	elseif inst:IsA("Decal") or inst:IsA("Texture") then
		remember(inst, "Transparency")
		inst.Transparency = 1
	elseif inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")
		or inst:IsA("Smoke") or inst:IsA("Fire") or inst:IsA("Sparkles")
		or inst:IsA("PostEffect") then
		remember(inst, "Enabled")
		inst.Enabled = false
	end
end

local boostBtn = makeButton(pgBoost, "ENABLE BOOST", 1, C.green)

local function enableBoost()
	boost.on = true
	boost.saved = {}
	boost.gen += 1
	local gen = boost.gen

	boost.prevShadows = shadowsOn
	setShadows(false)
	if shadowToggle then shadowToggle.set(false) end

	pcall(remember, Lighting, "FogEnd")
	pcall(function() Lighting.FogEnd = 9e9 end)

	local terrain = workspace:FindFirstChildOfClass("Terrain")
	if terrain then
		for _, p in ipairs({ "WaterWaveSize", "WaterWaveSpeed", "WaterReflectance", "WaterTransparency" }) do
			pcall(remember, terrain, p)
			pcall(function() terrain[p] = 0 end)
		end
	end

	pcall(function()
		local r = settings().Rendering
		remember(r, "QualityLevel")
		r.QualityLevel = Enum.QualityLevel.Level01
	end)

	task.spawn(function()
		for _, inst in ipairs(Lighting:GetChildren()) do pcall(optimize, inst) end
		local n = 0
		for _, inst in ipairs(workspace:GetDescendants()) do
			if boost.gen ~= gen or not boost.on then return end
			pcall(optimize, inst)
			n += 1
			if n % 400 == 0 then task.wait() end
		end
	end)
	boost.conn = workspace.DescendantAdded:Connect(function(inst)
		pcall(optimize, inst)
	end)

	boostBtn.Text = "DISABLE BOOST"
	boostBtn.BackgroundColor3 = C.red
	setStatus("Boost ON: shadows, textures, particles, effects reduced.")
end

local function disableBoost()
	boost.on = false
	boost.gen += 1
	if boost.conn then
		boost.conn:Disconnect()
		boost.conn = nil
	end
	local saved = boost.saved
	boost.saved = {}
	task.spawn(function()
		for i = #saved, 1, -1 do
			local v = saved[i]
			pcall(function() v[1][v[2]] = v[3] end)
			if i % 400 == 0 then task.wait() end
		end
	end)
	setShadows(boost.prevShadows)
	if shadowToggle then shadowToggle.set(boost.prevShadows) end

	boostBtn.Text = "ENABLE BOOST"
	boostBtn.BackgroundColor3 = C.green
	setStatus("Boost OFF: original settings restored.")
end

boostBtn.MouseButton1Click:Connect(function()
	if boost.on then disableBoost() else enableBoost() end
end)

shadowToggle = makeToggle(pgBoost, "Shadows", 2, shadowsOn, function(on)
	setShadows(on)
	setStatus(on and "Shadows ON." or "Shadows OFF.")
end)

------------------------------------------------------------
-- Dark textures
------------------------------------------------------------
local DARK = Color3.fromRGB(38, 38, 44)
local DARK_TEX = Color3.fromRGB(45, 45, 50)
local dark = { on = false, saved = {}, conn = nil, gen = 0 }

local function isCharPart(inst)
	local p = inst.Parent
	while p and p ~= workspace do
		if p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return true end
		p = p.Parent
	end
	return false
end

local function darken(inst)
	local s = dark.saved
	if inst:IsA("Terrain") then return end
	if inst:IsA("BasePart") then
		if isCharPart(inst) then return end
		s[#s + 1] = { inst, "Color", inst.Color }
		inst.Color = DARK
	elseif inst:IsA("Decal") or inst:IsA("Texture") then
		if isCharPart(inst) then return end
		s[#s + 1] = { inst, "Color3", inst.Color3 }
		inst.Color3 = DARK_TEX
	elseif inst:IsA("SurfaceAppearance") then
		s[#s + 1] = { inst, "Color", inst.Color }
		inst.Color = DARK_TEX
	end
end

local function setDark(on)
	dark.gen += 1
	local gen = dark.gen
	if on then
		dark.on = true
		dark.saved = {}
		for _, p in ipairs({ "Ambient", "OutdoorAmbient" }) do
			dark.saved[#dark.saved + 1] = { Lighting, p, Lighting[p] }
			Lighting[p] = Color3.fromRGB(32, 32, 38)
		end
		task.spawn(function()
			local n = 0
			for _, inst in ipairs(workspace:GetDescendants()) do
				if dark.gen ~= gen then return end
				pcall(darken, inst)
				n += 1
				if n % 400 == 0 then task.wait() end
			end
		end)
		dark.conn = workspace.DescendantAdded:Connect(function(inst)
			pcall(darken, inst)
		end)
		setStatus("Dark textures ON.")
	else
		dark.on = false
		if dark.conn then
			dark.conn:Disconnect()
			dark.conn = nil
		end
		local saved = dark.saved
		dark.saved = {}
		task.spawn(function()
			for i = #saved, 1, -1 do
				local v = saved[i]
				pcall(function() v[1][v[2]] = v[3] end)
				if i % 400 == 0 then task.wait() end
			end
		end)
		setStatus("Dark textures OFF.")
	end
end
makeToggle(pgBoost, "Dark Textures", 3, false, setDark)

