local logLabel = new("TextLabel", {
	LayoutOrder = 1000,
	Size = UDim2.new(1, -4, 0, 78),
	BackgroundColor3 = C.dark,
	BackgroundTransparency = 0.35,
	Font = Enum.Font.Code,
	TextSize = 11,
	TextWrapped = true,
	TextXAlignment = Enum.TextXAlignment.Left,
